/**
 * L2 — structural firewall. The highest-value layer and the closest true
 * DOMPurify analog: instead of judging text, change its REPRESENTATION so
 * untrusted content has no instruction authority and cannot escape its slot.
 *
 * Mechanism: every untrusted block is wrapped in a per-call random nonce
 * fence. The model is told (in trusted system text) that anything between
 * fences is data, never commands. Attacker cannot close the fence because
 * the nonce is unpredictable and any collision is neutralized.
 */

/**
 * Build a role-separated message array with untrusted parts fenced.
 * This is the recommended integration point — feed the result straight
 * to a chat completions API.
 */
declare function buildMessages(parts: MessageParts): ChatMessage[];

/**
 * promptpurify — structural prompt firewall.
 *
 * Philosophy (DOMPurify, honestly ported):
 *   • Whitelist/parse  -> impossible for natural language. We instead change
 *     REPRESENTATION (L2 nonce fencing) so untrusted text has no authority.
 *   • Deterministic    -> L1 normalize + L2 structure are pure & idempotent.
 *   • Context-aware    -> L3 sink policy (the HTML-body vs attr vs URL analog).
 *   • No false safety  -> there is NO `.safe` boolean. Semantic jailbreaks
 *     (persona/fiction/crescendo) are FLAGGED, never cleared. Documented gap.
 */

declare function createPromptPurify(config?: PurifyConfig): {
    sanitize: (dirty: string, opts?: {
        sink?: Sink;
    }) => string;
    inspect: (dirty: string, opts?: {
        sink?: Sink;
    }) => InspectReport;
    inspectAsync: (dirty: string, opts?: {
        sink?: Sink;
    }) => Promise<InspectReport>;
    buildMessages: typeof buildMessages;
    profile: Profile;
};
/** Default instance — `import { promptpurify } from "promptpurify"`. */
